('cloudmarkup_beta_billing_runtime','project_cleanup_controls',ARRAY['control_id','history_required','restore_status']::text[],ARRAY[]::text[],ARRAY[]::text[],false),
('cloudmarkup_beta_billing_runtime','project_content_erasure_receipts',ARRAY['deletion_record_version','deletion_requested_at','organization_id','project_id']::text[],ARRAY[]::text[],ARRAY[]::text[],false),
('cloudmarkup_beta_billing_runtime','project_content_writes',ARRAY['content_sha256','created_at','created_by_principal_id','finalized_at','history_id','lifecycle_status','object_id','organization_id','project_id','storage_namespace','write_id']::text[],ARRAY[]::text[],ARRAY[]::text[],false),
('cloudmarkup_beta_billing_runtime','project_deletion_recovery_objects',ARRAY['content_sha256','created_at','created_by_principal_id','deletion_record_version','finalized_at','history_id','job_id','job_record_version','lifecycle_status','media_type','object_id','object_purpose','organization_id','project_id','size_bytes']::text[],ARRAY[]::text[],ARRAY[]::text[],false),
('cloudmarkup_beta_billing_runtime','projects',ARRAY['deletion_requested_at','lifecycle_status','organization_id','project_id','record_version']::text[],ARRAY[]::text[],ARRAY[]::text[],false),
('cloudmarkup_beta_billing_runtime','usage_ledger_entries',ARRAY['acting_principal_id','billing_account_id','cached_input_token_count','charging_policy_version','charging_scenario','correlation_id','credit_adjustment_units','credit_grant_id','entitlement_policy_version','entry_kind','estimated_provider_cost_micros','expired_credit_units','feature_key','granted_credit_units','idempotency_key_sha256','input_token_count','job_id','latency_milliseconds','ledger_entry_id','legacy_pricing_version_id','model_key','model_pricing_version_id','model_version','normalized_credit_units','occurred_at','organization_id','outcome','output_token_count','plan_version_id','pricing_authority','pricing_version_id','project_id','provider_cost_currency','provider_key','provider_request_id','reason_code','recorded_by_actor_id','recorded_by_actor_kind','related_ledger_entry_id','released_credit_units','request_id','reservation_id','reserved_credit_units','safe_reason','settled_credit_units','storage_contract_version']::text[],ARRAY['acting_principal_id','billing_account_id','charging_policy_version','correlation_id','credit_adjustment_units','credit_grant_id','entry_kind','granted_credit_units','idempotency_key_sha256','ledger_entry_id','organization_id','outcome','plan_version_id','reason_code','recorded_by_actor_id','recorded_by_actor_kind','related_ledger_entry_id','safe_reason']::text[],ARRAY[]::text[],false),
('cloudmarkup_beta_billing_runtime','usage_ledger_entry_allocations',ARRAY['allocation_sequence','credit_adjustment_units','credit_grant_id','expired_credit_units','ledger_entry_id','organization_id','released_credit_units','reserved_credit_units','settled_credit_units']::text[],ARRAY[]::text[],ARRAY[]::text[],false),
('cloudmarkup_beta_api_runtime','cloudmarkup_schema_migrations',ARRAY['version','checksum_sha256']::text[],ARRAY[]::text[],ARRAY[]::text[],false),
('cloudmarkup_beta_proposal_runtime','cloudmarkup_schema_migrations',ARRAY['version','checksum_sha256']::text[],ARRAY[]::text[],ARRAY[]::text[],false),
('cloudmarkup_beta_export_runtime','cloudmarkup_schema_migrations',ARRAY['version','checksum_sha256']::text[],ARRAY[]::text[],ARRAY[]::text[],false),
('cloudmarkup_beta_cleanup_runtime','cloudmarkup_schema_migrations',ARRAY['version','checksum_sha256']::text[],ARRAY[]::text[],ARRAY[]::text[],false),
('cloudmarkup_beta_billing_runtime','cloudmarkup_schema_migrations',ARRAY['version','checksum_sha256']::text[],ARRAY[]::text[],ARRAY[]::text[],false)),
  lock_columns(login,table_name,column_name) AS (VALUES ('cloudmarkup_beta_api_runtime','architecture_revisions','revision_id'),('cloudmarkup_beta_api_runtime','credit_grants','credit_grant_id'),('cloudmarkup_beta_api_runtime','commercial_plan_versions','plan_version_id'),('cloudmarkup_beta_api_runtime','commercial_plan_seat_rules','plan_version_id'),('cloudmarkup_beta_api_runtime','commercial_plan_numeric_limits','plan_version_id'),('cloudmarkup_beta_api_runtime','solution_records','solution_record_id'),('cloudmarkup_beta_export_runtime','solution_records','solution_record_id'),('cloudmarkup_beta_api_runtime','async_job_record_snapshots','job_id'),('cloudmarkup_beta_export_runtime','async_job_record_snapshots','job_id'),('cloudmarkup_beta_api_runtime','solution_export_artifacts','solution_export_artifact_id'),('cloudmarkup_beta_export_runtime','solution_export_artifacts','solution_export_artifact_id'),('cloudmarkup_beta_export_runtime','async_job_creation_claims','job_id'),('cloudmarkup_beta_api_runtime','solution_export_download_grants','organization_id'),('cloudmarkup_beta_api_runtime','ai_intent_preview_authorities','invocation_id')),
  hosts(login) AS (VALUES ('cloudmarkup_beta_api_runtime'),('cloudmarkup_beta_proposal_runtime'),('cloudmarkup_beta_export_runtime'),('cloudmarkup_beta_cleanup_runtime'),('cloudmarkup_beta_billing_runtime')),
  schema_failures AS (
    SELECT 'schema-acl:'||h.login||':'||required.name AS failure
    FROM hosts h CROSS JOIN (VALUES ('public'),('cloudmarkup_ordinary_private')) required(name)
    LEFT JOIN pg_catalog.pg_namespace n ON n.nspname=required.name
    LEFT JOIN pg_catalog.pg_roles owner ON owner.oid=n.nspowner
    WHERE n.oid IS NULL OR NOT pg_catalog.has_schema_privilege(h.login,n.oid,'USAGE')
      OR pg_catalog.has_schema_privilege(h.login,n.oid,'CREATE')
      OR pg_catalog.has_schema_privilege(h.login,n.oid,'USAGE WITH GRANT OPTION,CREATE WITH GRANT OPTION')
      OR (required.name='cloudmarkup_ordinary_private' AND (
        owner.rolname IS DISTINCT FROM 'cloudmarkup_admin'
        OR EXISTS(SELECT 1 FROM pg_catalog.aclexplode(COALESCE(n.nspacl,pg_catalog.acldefault('n',n.nspowner))) a WHERE a.grantee=0 AND a.privilege_type IN ('USAGE','CREATE'))))
  ),
  column_failures AS (
    SELECT 'column-acl:'||h.login||':'||t.relname||'.'||a.attname AS failure
    FROM hosts h CROSS JOIN pg_catalog.pg_class t
    JOIN pg_catalog.pg_namespace n ON n.oid=t.relnamespace
    JOIN pg_catalog.pg_attribute a ON a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped
    LEFT JOIN expected e ON e.login=h.login AND e.table_name=t.relname
    WHERE n.nspname='public' AND t.relkind IN ('r','p') AND (
      pg_catalog.has_column_privilege(h.login,t.oid,a.attnum,'SELECT') IS DISTINCT FROM COALESCE(a.attname=ANY(e.select_cols),false)
      OR pg_catalog.has_column_privilege(h.login,t.oid,a.attnum,'INSERT') IS DISTINCT FROM COALESCE(a.attname=ANY(e.insert_cols),false)
      OR pg_catalog.has_column_privilege(h.login,t.oid,a.attnum,'UPDATE') IS DISTINCT FROM (COALESCE(a.attname=ANY(e.update_cols),false) OR EXISTS(SELECT 1 FROM lock_columns l WHERE l.login=h.login AND l.table_name=t.relname AND l.column_name=a.attname))
      OR pg_catalog.has_column_privilege(h.login,t.oid,a.attnum,'SELECT WITH GRANT OPTION,INSERT WITH GRANT OPTION,UPDATE WITH GRANT OPTION'))
  ), table_failures AS (
    SELECT 'table-acl:'||h.login||':'||t.relname AS failure FROM hosts h CROSS JOIN pg_catalog.pg_class t
    JOIN pg_catalog.pg_namespace n ON n.oid=t.relnamespace
    LEFT JOIN expected e ON e.login=h.login AND e.table_name=t.relname
    WHERE n.nspname='public' AND t.relkind IN ('r','p') AND (
      pg_catalog.has_table_privilege(h.login,t.oid,'SELECT,INSERT,UPDATE,TRUNCATE,REFERENCES,TRIGGER')
      OR pg_catalog.has_table_privilege(h.login,t.oid,'DELETE') IS DISTINCT FROM COALESCE(e.delete_allowed,false)
      OR pg_catalog.has_table_privilege(h.login,t.oid,'DELETE WITH GRANT OPTION'))
  ), sequence_failures AS (
    SELECT 'sequence-acl:'||h.login||':'||t.relname AS failure FROM hosts h CROSS JOIN pg_catalog.pg_class t
    JOIN pg_catalog.pg_namespace n ON n.oid=t.relnamespace
    WHERE n.nspname='public' AND t.relkind='S' AND pg_catalog.has_sequence_privilege(h.login,t.oid,'USAGE,SELECT,UPDATE')
  ), missing_tables AS (
    SELECT 'missing-table:'||e.login||':'||e.table_name AS failure FROM expected e
    WHERE pg_catalog.to_regclass('public.'||e.table_name) IS NULL
  )
SELECT failure FROM schema_failures UNION ALL SELECT failure FROM column_failures UNION ALL SELECT failure FROM table_failures UNION ALL SELECT failure FROM sequence_failures UNION ALL SELECT failure FROM missing_tables ORDER BY failure;
